import pytest

from tests.media import H264, TEST_PICTURE, TEST_SOUND, run_ffmpeg


@pytest.fixture
def synthetic_video(tmp_path):
    """A 1-second test video with sound, generated by ffmpeg: never real footage."""
    path = tmp_path / 'synthetic.mp4'
    run_ffmpeg(
        '-f', 'lavfi', '-i', 'testsrc=duration=1:size=320x240:rate=10',
        *TEST_SOUND, *H264, '-c:a', 'aac', '-shortest', str(path),
    )
    return path


@pytest.fixture
def make_media(tmp_path):
    """Make a small synthetic media file: make_media('name.ext', *ffmpeg output options).

    Inputs are a test picture and a test tone; pass '-an' or '-vn' to drop one, and
    '-metadata', 'key=value' to add fake tags such as a GPS position.
    """
    def make(name, *options):
        path = tmp_path / name
        run_ffmpeg(*TEST_PICTURE, *TEST_SOUND, *options, '-shortest', str(path))
        return path
    return make
